    station = c.named(g, 'st_cd_station'); half = c.named(g, 'st_cd_half')
    active = c.named(g, 'st_cd_active', 'BOOLEAN')
    # A small inward reserve makes the construction conservative in float32.
    # It does not increase any acceptance tolerance or shorten a taper.
    reserve = 1e-4
    available_start = g.math('MAXIMUM', station-c.named(g, 'st_cd_before_length'), c.V(g, inp.outputs['Start Cut']))
